document.addEventListener('click',event=>{if(Date.now()<suppressClickUntil)return;const target=event.target.closest('[data-action]');if(target&&!target.disabled){event.preventDefault();action(target.dataset.action);}});
document.addEventListener('input',event=>{if(event.target.id==='page-query')$$('#page-results button,#page-results a').forEach(e=>e.hidden=!normalize(e.textContent).includes(normalize(event.target.value)));if(event.target.id==='order-query'){const pos=event.target.selectionStart,scroll=$('#main-content').scrollTop;state.query=event.target.value;state.tablePage=1;$('#main-content').innerHTML=gestorHtml();const input=$('#order-query');input.focus();if(pos!==null)input.setSelectionRange(pos,pos);$('#main-content').scrollTop=scroll;}});
document.addEventListener('change',event=>{const id=event.target.dataset.selectOrder;if(id){event.target.checked?state.selected.add(id):state.selected.delete(id);render();$('[data-select-order="'+id+'"]')?.focus();}});
$('#modal').addEventListener('cancel',event=>{event.preventDefault();close();});$('#modal').addEventListener('close',()=>{if($('#modal').open)return;modalDirty=false;discardFooter=null;if(previousFocus?.isConnected)previousFocus.focus();else $('#main-content').focus();});
$('#tabs').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const nodes=$$('button',$('#tabs')),at=nodes.indexOf(event.target);if(at<0)return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?nodes.length-1:(at+(event.key==='ArrowRight'?1:-1)+nodes.length)%nodes.length;nodes[next].focus();nodes[next].scrollIntoView({block:'nearest',inline:'nearest'});});
// Swipe e toque longo são caminhos adicionais, com o mesmo alvo e guardas do botão.
document.addEventListener('pointerdown',event=>{const row=event.target.closest('[data-swipe]'),card=event.target.closest('[data-ticket]');if(app!=='kds'||!row&&!card||event.target.closest('button[data-action]')&&!row)return;const id=row?.dataset.swipe||card?.dataset.ticket;gesture={id,x:event.clientX,y:event.clientY,row:Boolean(row)};holdTimer=setTimeout(()=>{suppressClickUntil=Date.now()+450;action('ticket-menu:'+id);gesture=null;},550);});
document.addEventListener('pointermove',event=>{if(!gesture)return;if(Math.abs(event.clientX-gesture.x)>10||Math.abs(event.clientY-gesture.y)>10){clearTimeout(holdTimer);holdTimer=null;}});
document.addEventListener('pointerup',event=>{clearTimeout(holdTimer);if(!gesture)return;const g=gesture;gesture=null;if(g.row&&event.clientX-g.x>80&&Math.abs(event.clientY-g.y)<40){const t=tickets.find(t=>t.id===g.id),a=ticketAct(t);if(a?.kind==='finish'&&!a.disabled){suppressClickUntil=Date.now()+300;finishTicket(t);}}});
document.addEventListener('pointercancel',()=>{clearTimeout(holdTimer);gesture=null;});
document.addEventListener('contextmenu',event=>{if(app==='kds'&&event.target.closest('[data-swipe],[data-ticket]'))event.preventDefault();});
let splitDrag=null;document.addEventListener('pointerdown',event=>{const handle=event.target.closest('[data-column-handle]');if(!handle)return;const board=$('#order-columns'),cols=$$('.board-column',board);splitDrag={index:Number(handle.dataset.columnHandle),x:event.clientX,widths:cols.map(c=>c.getBoundingClientRect().width)};handle.setPointerCapture(event.pointerId);event.preventDefault();});
document.addEventListener('pointermove',event=>{if(!splitDrag)return;const widths=[...splitDrag.widths],i=splitDrag.index-1,delta=event.clientX-splitDrag.x,max=widths[i]+widths[i+1];widths[i]=Math.max(200,Math.min(max-200,widths[i]+delta));widths[i+1]=max-widths[i];state.columnWeights=widths;$('#order-columns').style.gridTemplateColumns=widths.map(w=>'minmax(0,'+w+'fr)').join(' 7px ');});
document.addEventListener('pointerup',()=>splitDrag=null);document.addEventListener('keydown',event=>{const handle=event.target.closest('[data-column-handle]');if(!handle||!['ArrowLeft','ArrowRight','Home'].includes(event.key))return;event.preventDefault();const board=$('#order-columns');if(event.key==='Home'){board.style.gridTemplateColumns=$$('.board-column',board).map(()=>'minmax(0,1fr)').join(' 7px ');state.columnWeights=null;return;}const widths=$$('.board-column',board).map(c=>c.getBoundingClientRect().width),i=Number(handle.dataset.columnHandle)-1,delta=event.key==='ArrowRight'?20:-20;if(widths[i]+delta<200||widths[i+1]-delta<200)return;widths[i]+=delta;widths[i+1]-=delta;state.columnWeights=widths;board.style.gridTemplateColumns=widths.map(w=>'minmax(0,'+w+'fr)').join(' 7px ');});
let previousDesk=isDesk(),previousPhone=phoneKds();window.addEventListener('resize',()=>{fitAggregate();if(previousDesk!==isDesk()||previousPhone!==phoneKds()){previousDesk=isDesk();previousPhone=phoneKds();render();}});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);if(app==='kds'&&STATIONS[p.get('station')])state.station=p.get('station');if(app==='gestor'){state.screen=p.get('screen')==='exit'?'exit':'office';state.view=['queue','board','table'].includes(p.get('view'))?p.get('view'):'queue';}render();});
if(app==='kds')setInterval(()=>{if(state.doneUntil.size)updateCountdowns();},100);render();
